from frappe.utils.safe_exec import safe_exec
REPORT_SCRIPT='# Indicator Performance Tracking Table v2.1 - Exact Project Cycle Mapping\r\n# Frappe / ERPNext 16 Custom Script Report - Safe Execution\r\n\r\nfilters = filters or {}\r\nview_mode = filters.get("view_mode") or "Standard IPTT"\r\nlayout_mode = filters.get("layout_mode") or "Period Rows"\r\nperiod_grouping = filters.get("period_grouping") or "Plan Period"\r\nmatrix_measure = filters.get("matrix_measure") or "Target and Actual"\r\n\r\nbase_columns = [\r\n    {"label": _("Project"), "fieldname": "project", "fieldtype": "Link", "options": "Project", "width": 125},\r\n    {"label": _("Project Name"), "fieldname": "project_name", "fieldtype": "Data", "width": 210},\r\n    {"label": _("Stage"), "fieldname": "project_stage", "fieldtype": "Data", "width": 125},\r\n    {"label": _("Result"), "fieldname": "result_title", "fieldtype": "Data", "width": 190},\r\n    {"label": _("Indicator Code"), "fieldname": "indicator_code", "fieldtype": "Data", "width": 100},\r\n    {"label": _("Indicator"), "fieldname": "indicator_name", "fieldtype": "Link", "options": "Project Indicator", "width": 250},\r\n    {"label": _("Indicator Level"), "fieldname": "indicator_level", "fieldtype": "Data", "width": 105},\r\n    {"label": _("Indicator Source"), "fieldname": "indicator_source", "fieldtype": "Data", "width": 130},\r\n    {"label": _("Unit"), "fieldname": "unit_of_measure", "fieldtype": "Data", "width": 85},\r\n    {"label": _("Aggregation"), "fieldname": "aggregation_method", "fieldtype": "Data", "width": 145},\r\n    {"label": _("Direction"), "fieldname": "improvement_direction", "fieldtype": "Data", "width": 110},\r\n    {"label": _("Baseline"), "fieldname": "baseline", "fieldtype": "Float", "width": 80},\r\n    {"label": _("LOA Target"), "fieldname": "overall_target", "fieldtype": "Float", "width": 90},\r\n    {"label": _("Period"), "fieldname": "period_label", "fieldtype": "Data", "width": 115},\r\n    {"label": _("Period Start"), "fieldname": "period_start", "fieldtype": "Date", "width": 95},\r\n    {"label": _("Period End"), "fieldname": "period_end", "fieldtype": "Date", "width": 95},\r\n    {"label": _("Period Target"), "fieldname": "period_target", "fieldtype": "Float", "width": 95},\r\n    {"label": _("Period Actual"), "fieldname": "period_actual", "fieldtype": "Float", "width": 95},\r\n    {"label": _("Cumulative Target"), "fieldname": "cumulative_target", "fieldtype": "Float", "width": 115},\r\n    {"label": _("Cumulative Actual"), "fieldname": "cumulative_actual", "fieldtype": "Float", "width": 115},\r\n    {"label": _("Achievement"), "fieldname": "achievement_percentage", "fieldtype": "Percent", "width": 95},\r\n    {"label": _("Variance"), "fieldname": "variance", "fieldtype": "Float", "width": 85},\r\n    {"label": _("Performance"), "fieldname": "performance_status", "fieldtype": "Data", "width": 120},\r\n    {"label": _("Data Quality"), "fieldname": "data_quality", "fieldtype": "Data", "width": 120},\r\n    {"label": _("Reporting Update"), "fieldname": "progress_update", "fieldtype": "Link", "options": "Project Progress Update", "width": 145},\r\n    {"label": _("Reporting Date"), "fieldname": "last_result_date", "fieldtype": "Date", "width": 100},\r\n    {"label": _("Frequency"), "fieldname": "frequency", "fieldtype": "Data", "width": 95},\r\n    {"label": _("Collection Responsible"), "fieldname": "collection_responsible_name", "fieldtype": "Data", "width": 150},\r\n    {"label": _("Verification Responsible"), "fieldname": "verification_responsible_name", "fieldtype": "Data", "width": 150},\r\n    {"label": _("Approval Responsible"), "fieldname": "approval_responsible_name", "fieldtype": "Data", "width": 145},\r\n    {"label": _("Data Source"), "fieldname": "data_source", "fieldtype": "Data", "width": 165},\r\n    {"label": _("Means of Verification"), "fieldname": "means_of_verification", "fieldtype": "Data", "width": 175},\r\n    {"label": _("Result Narrative"), "fieldname": "comments", "fieldtype": "Data", "width": 220},\r\n    {"label": _("Variance Reason"), "fieldname": "variance_reason", "fieldtype": "Data", "width": 190},\r\n    {"label": _("Corrective Action"), "fieldname": "corrective_action", "fieldtype": "Data", "width": 190}\r\n]\r\n\r\nif view_mode == "Donor IPTT":\r\n    column_names = ["project", "project_name", "result_title", "indicator_code", "indicator_name", "indicator_level", "unit_of_measure", "baseline", "overall_target", "period_label", "period_target", "period_actual", "cumulative_target", "cumulative_actual", "achievement_percentage", "variance", "performance_status", "data_source", "means_of_verification", "comments", "variance_reason"]\r\nelif view_mode == "M&E":\r\n    column_names = [x.get("fieldname") for x in base_columns]\r\nelif view_mode == "Period Performance":\r\n    column_names = ["project", "project_name", "indicator_code", "indicator_name", "unit_of_measure", "aggregation_method", "period_label", "period_start", "period_end", "period_target", "period_actual", "achievement_percentage", "performance_status", "data_quality", "progress_update", "comments"]\r\nelif view_mode == "Cumulative Performance":\r\n    column_names = ["project", "project_name", "indicator_code", "indicator_name", "unit_of_measure", "aggregation_method", "improvement_direction", "baseline", "overall_target", "period_label", "cumulative_target", "cumulative_actual", "achievement_percentage", "variance", "performance_status", "last_result_date"]\r\nelif view_mode == "Full":\r\n    column_names = [x.get("fieldname") for x in base_columns]\r\nelse:\r\n    column_names = ["project", "project_name", "project_stage", "result_title", "indicator_code", "indicator_name", "indicator_level", "unit_of_measure", "baseline", "overall_target", "period_label", "period_target", "period_actual", "cumulative_target", "cumulative_actual", "achievement_percentage", "variance", "performance_status", "data_quality", "last_result_date", "comments"]\r\ncolumns = []\r\nfor base_column in base_columns:\r\n    if base_column.get("fieldname") in column_names:\r\n        columns.append(base_column)\r\n\r\nindicator_fields = [\r\n    "name", "project", "project_result", "indicator_code", "indicator_name", "indicator_level", "indicator_source",\r\n    "unit_of_measure", "aggregation_method", "improvement_direction", "baseline_value", "life_of_project_target",\r\n    "reporting_frequency", "data_collection_responsible", "data_verification_responsible", "approval_responsible",\r\n    "data_source", "means_of_verification", "latest_approved_period_actual", "approved_cumulative_actual",\r\n    "latest_cumulative_target", "achievement_percentage", "last_reporting_period", "last_reporting_date",\r\n    "latest_data_quality_status", "latest_approved_progress_update", "indicator_performance_status", "status"\r\n]\r\nindicator_filters = {}\r\nproject_values = filters.get("project") or []\r\nif project_values:\r\n    indicator_filters["project"] = ["in", project_values]\r\nindicator_values = filters.get("indicator") or []\r\nif indicator_values:\r\n    indicator_filters["name"] = ["in", indicator_values]\r\nindicator_type_values = filters.get("indicator_type") or []\r\nif indicator_type_values:\r\n    indicator_filters["indicator_level"] = ["in", indicator_type_values]\r\nindicators = frappe.get_all("Project Indicator", filters=indicator_filters, fields=indicator_fields, order_by="project asc, sequence asc, indicator_code asc", limit_page_length=0)\r\n\r\nrows = []\r\nfor indicator in indicators:\r\n    project_name = indicator.get("project") or ""\r\n    project = frappe.db.get_value("Project", project_name, ["project_name", "custom_project_stage", "custom_project_manager", "expected_start_date"], as_dict=True) if project_name else None\r\n    project_title = project.get("project_name") if project else ""\r\n    project_stage = project.get("custom_project_stage") if project else ""\r\n    project_start_date = project.get("expected_start_date") if project else None\r\n    manager = project.get("custom_project_manager") if project else ""\r\n    manager_name = frappe.db.get_value("Employee", manager, "employee_name") if manager else ""\r\n    result_title = ""\r\n    result_name = indicator.get("project_result") or ""\r\n    if result_name:\r\n        result_title = frappe.db.get_value("Project Result", result_name, "result_statement") or result_name\r\n\r\n    collection_responsible = indicator.get("data_collection_responsible") or ""\r\n    verification_responsible = indicator.get("data_verification_responsible") or ""\r\n    approval_responsible = indicator.get("approval_responsible") or ""\r\n    collection_name = frappe.db.get_value("Employee", collection_responsible, "employee_name") if collection_responsible else ""\r\n    verification_name = frappe.db.get_value("Employee", verification_responsible, "employee_name") if verification_responsible else ""\r\n    approval_name = frappe.db.get_value("Employee", approval_responsible, "employee_name") if approval_responsible else ""\r\n\r\n    plans = frappe.get_all(\r\n        "Indicator Target Plan",\r\n        filters={"project": project_name, "indicator": indicator.get("name")},\r\n        fields=["name", "period_type", "period_label", "period_start_date", "period_end_date", "sequence", "period_target", "cumulative_target", "status", "target_scope", "governorate", "district", "implementation_partner", "donor"],\r\n        order_by="period_start_date asc, sequence asc",\r\n        limit_page_length=0\r\n    )\r\n\r\n    approved_updates = frappe.get_all(\r\n        "Project Progress Update",\r\n        filters={"project": project_name, "status": "Approved"},\r\n        fields=["name", "reporting_period_label", "period_start_date", "period_end_date", "cutoff_date", "approved_on", "status"],\r\n        order_by="period_end_date asc, approved_on asc",\r\n        limit_page_length=0\r\n    )\r\n    update_names = []\r\n    update_map = {}\r\n    for approved_update in approved_updates:\r\n        update_names.append(approved_update.get("name"))\r\n        update_map[approved_update.get("name")] = approved_update\r\n\r\n    result_entries = []\r\n    if update_names:\r\n        result_entries = frappe.get_all(\r\n            "Indicator Result Entry",\r\n            filters={"parent": ["in", update_names], "parenttype": "Project Progress Update", "parentfield": "indicator_result_entries", "indicator": indicator.get("name")},\r\n            fields=["name", "parent", "indicator", "period_target", "cumulative_target", "period_actual", "cumulative_actual", "achievement_percentage", "period_numerator", "period_denominator", "cumulative_numerator", "cumulative_denominator", "data_quality_status", "result_narrative", "variance_reason", "corrective_action", "means_of_verification"],\r\n            order_by="parent asc, idx asc",\r\n            limit_page_length=0\r\n        )\r\n\r\n    if not plans:\r\n        plans = [{\r\n            "name": "", "period_label": indicator.get("last_reporting_period") or _("Overall"),\r\n            "period_start_date": None, "period_end_date": indicator.get("last_reporting_date"),\r\n            "period_target": indicator.get("latest_cumulative_target") or indicator.get("life_of_project_target") or 0,\r\n            "cumulative_target": indicator.get("latest_cumulative_target") or indicator.get("life_of_project_target") or 0,\r\n            "status": "Summary"\r\n        }]\r\n\r\n    running_target = 0.0\r\n    running_actual = 0.0\r\n    running_count = 0\r\n    for plan in plans:\r\n        period_start = plan.get("period_start_date")\r\n        period_end = plan.get("period_end_date")\r\n        period_target = float(plan.get("period_target") or 0)\r\n        running_target += period_target\r\n        cumulative_target = float(plan.get("cumulative_target") or 0)\r\n        if cumulative_target == 0 and indicator.get("aggregation_method") == "Cumulative Sum":\r\n            cumulative_target = running_target\r\n        elif cumulative_target == 0:\r\n            cumulative_target = period_target\r\n\r\n        matching_entries = []\r\n        for result_entry in result_entries:\r\n            update = update_map.get(result_entry.get("parent")) or {}\r\n            update_start = update.get("period_start_date")\r\n            update_end = update.get("period_end_date")\r\n            overlaps = True\r\n            if period_start and update_end and str(update_end) < str(period_start):\r\n                overlaps = False\r\n            if period_end and update_start and str(update_start) > str(period_end):\r\n                overlaps = False\r\n            if overlaps:\r\n                matching_entries.append(result_entry)\r\n\r\n        latest_entry = matching_entries[-1] if matching_entries else None\r\n        period_actual = float(latest_entry.get("period_actual") or 0) if latest_entry else 0.0\r\n        cumulative_actual = float(latest_entry.get("cumulative_actual") or 0) if latest_entry else 0.0\r\n        aggregation_method = indicator.get("aggregation_method") or ""\r\n        if not latest_entry:\r\n            if not plan.get("name"):\r\n                period_actual = float(indicator.get("latest_approved_period_actual") or 0)\r\n                cumulative_actual = float(indicator.get("approved_cumulative_actual") or 0)\r\n        elif cumulative_actual == 0:\r\n            if aggregation_method == "Cumulative Sum":\r\n                running_actual += period_actual\r\n                cumulative_actual = running_actual\r\n            elif aggregation_method == "Average":\r\n                running_actual += period_actual\r\n                running_count += 1\r\n                cumulative_actual = running_actual / running_count if running_count else 0\r\n            else:\r\n                cumulative_actual = period_actual\r\n        else:\r\n            running_actual = cumulative_actual\r\n\r\n        improvement_direction = indicator.get("improvement_direction") or "Higher is Better"\r\n        achievement_percentage = 0.0\r\n        if cumulative_target > 0:\r\n            if improvement_direction == "Lower is Better":\r\n                achievement_percentage = cumulative_target * 100 / cumulative_actual if cumulative_actual > 0 else 100\r\n            elif improvement_direction == "Maintain":\r\n                achievement_percentage = 100 - (abs(cumulative_actual - cumulative_target) * 100 / cumulative_target)\r\n                if achievement_percentage < 0:\r\n                    achievement_percentage = 0\r\n            else:\r\n                achievement_percentage = cumulative_actual * 100 / cumulative_target\r\n        variance = cumulative_actual - cumulative_target\r\n        performance_status = "Not Assessed"\r\n        if cumulative_target > 0:\r\n            if achievement_percentage >= 110:\r\n                performance_status = "Exceeded Target"\r\n            elif achievement_percentage >= 100:\r\n                performance_status = "Target Achieved"\r\n            elif achievement_percentage >= 90:\r\n                performance_status = "On Track"\r\n            elif achievement_percentage >= 70:\r\n                performance_status = "At Risk"\r\n            else:\r\n                performance_status = "Critical"\r\n\r\n        update_name = latest_entry.get("parent") if latest_entry else indicator.get("latest_approved_progress_update") or ""\r\n        update = update_map.get(update_name) or {}\r\n        data_quality = latest_entry.get("data_quality_status") if latest_entry else indicator.get("latest_data_quality_status") or "Not Assessed"\r\n        comments = latest_entry.get("result_narrative") if latest_entry else ""\r\n        variance_reason = latest_entry.get("variance_reason") if latest_entry else ""\r\n        corrective_action = latest_entry.get("corrective_action") if latest_entry else ""\r\n        means_of_verification = latest_entry.get("means_of_verification") if latest_entry and latest_entry.get("means_of_verification") else indicator.get("means_of_verification") or ""\r\n        last_result_date = update.get("cutoff_date") or update.get("period_end_date") or indicator.get("last_reporting_date")\r\n\r\n        from_date = filters.get("from_date") or ""\r\n        to_date = filters.get("to_date") or ""\r\n        if from_date and period_end and str(period_end) < str(from_date):\r\n            continue\r\n        if to_date and period_start and str(period_start) > str(to_date):\r\n            continue\r\n        status_values = filters.get("performance_status") or []\r\n        if status_values and performance_status not in status_values:\r\n            continue\r\n        quality_values = filters.get("data_quality") or []\r\n        if quality_values and data_quality not in quality_values:\r\n            continue\r\n        if int(filters.get("below_target_only") or 0) == 1 and performance_status not in ["At Risk", "Critical"]:\r\n            continue\r\n        if int(filters.get("not_updated_only") or 0) == 1 and latest_entry:\r\n            continue\r\n\r\n        rows.append({\r\n            "project": project_name, "project_name": project_title, "project_stage": project_stage,\r\n            "project_start_date": project_start_date, "project_manager": manager, "project_manager_name": manager_name,\r\n            "result_title": result_title, "indicator_name": indicator.get("name"), "indicator_code": indicator.get("indicator_code"),\r\n            "indicator_statement": indicator.get("indicator_name"), "indicator_level": indicator.get("indicator_level"),\r\n            "indicator_source": indicator.get("indicator_source"), "unit_of_measure": indicator.get("unit_of_measure"),\r\n            "aggregation_method": aggregation_method, "improvement_direction": improvement_direction,\r\n            "baseline": float(indicator.get("baseline_value") or 0), "overall_target": float(indicator.get("life_of_project_target") or 0),\r\n            "period_label": plan.get("period_label") or _("Overall"), "period_start": period_start, "period_end": period_end,\r\n            "period_target": period_target, "period_actual": period_actual, "cumulative_target": cumulative_target,\r\n            "cumulative_actual": cumulative_actual, "achievement_percentage": achievement_percentage, "variance": variance,\r\n            "performance_status": performance_status, "data_quality": data_quality, "progress_update": update_name,\r\n            "last_result_date": last_result_date, "frequency": indicator.get("reporting_frequency"),\r\n            "collection_responsible_name": collection_name, "verification_responsible_name": verification_name,\r\n            "approval_responsible_name": approval_name, "data_source": indicator.get("data_source"),\r\n            "means_of_verification": means_of_verification, "comments": comments, "variance_reason": variance_reason,\r\n            "corrective_action": corrective_action\r\n        })\r\n\r\nif layout_mode in ["Period Matrix", "Cumulative Matrix"]:\r\n    source_rows = rows\r\n    matrix_map = {}\r\n    period_registry = []\r\n    for source_row in source_rows:\r\n        source_date = source_row.get("period_start") or source_row.get("period_end")\r\n        period_label = source_row.get("period_label") or _("Overall")\r\n        sort_value = str(source_row.get("period_start") or source_row.get("period_end") or period_label)\r\n        if period_grouping == "Month" and source_date:\r\n            period_label = str(source_date)[0:7]\r\n            sort_value = period_label\r\n        elif period_grouping == "Quarter" and source_date:\r\n            date_text = str(source_date)\r\n            quarter = int((int(date_text[5:7]) - 1) / 3) + 1\r\n            period_label = date_text[0:4] + " Q" + str(quarter)\r\n            sort_value = date_text[0:4] + "-" + str(quarter)\r\n        elif period_grouping == "Calendar Year" and source_date:\r\n            period_label = str(source_date)[0:4]\r\n            sort_value = period_label\r\n        elif period_grouping == "Project Year" and source_date and source_row.get("project_start_date"):\r\n            date_text = str(source_date)\r\n            start_text = str(source_row.get("project_start_date"))\r\n            date_index = int(date_text[0:4]) * 12 + int(date_text[5:7])\r\n            start_index = int(start_text[0:4]) * 12 + int(start_text[5:7])\r\n            year_number = int((date_index - start_index) / 12) + 1\r\n            if year_number < 1:\r\n                year_number = 1\r\n            period_label = _("Year") + " " + str(year_number)\r\n            sort_value = str(year_number).zfill(4)\r\n\r\n        token = ""\r\n        for char in str(period_label).lower():\r\n            if (char >= "a" and char <= "z") or (char >= "0" and char <= "9"):\r\n                token += char\r\n            else:\r\n                token += "_"\r\n        while "__" in token:\r\n            token = token.replace("__", "_")\r\n        token = token.strip("_") or "period"\r\n        registry_value = sort_value + "|||" + period_label + "|||" + token\r\n        if registry_value not in period_registry:\r\n            period_registry.append(registry_value)\r\n        matrix_key = str(source_row.get("project")) + "|||" + str(source_row.get("indicator_name"))\r\n        if matrix_key not in matrix_map:\r\n            matrix_map[matrix_key] = {\r\n                "project": source_row.get("project"), "project_name": source_row.get("project_name"),\r\n                "result_title": source_row.get("result_title"), "indicator_code": source_row.get("indicator_code"),\r\n                "indicator_name": source_row.get("indicator_name"), "indicator_statement": source_row.get("indicator_statement"),\r\n                "indicator_level": source_row.get("indicator_level"), "unit_of_measure": source_row.get("unit_of_measure"),\r\n                "aggregation_method": source_row.get("aggregation_method"), "improvement_direction": source_row.get("improvement_direction"),\r\n                "baseline": source_row.get("baseline"), "overall_target": source_row.get("overall_target"),\r\n                "frequency": source_row.get("frequency"), "collection_responsible_name": source_row.get("collection_responsible_name"),\r\n                "verification_responsible_name": source_row.get("verification_responsible_name"),\r\n                "data_source": source_row.get("data_source"), "means_of_verification": source_row.get("means_of_verification")\r\n            }\r\n        target_value = float(source_row.get("period_target") or 0)\r\n        actual_value = float(source_row.get("period_actual") or 0)\r\n        if layout_mode == "Cumulative Matrix":\r\n            target_value = float(source_row.get("cumulative_target") or 0)\r\n            actual_value = float(source_row.get("cumulative_actual") or 0)\r\n        matrix_row = matrix_map[matrix_key]\r\n        target_key = "p_" + token + "_target"\r\n        actual_key = "p_" + token + "_actual"\r\n        achievement_key = "p_" + token + "_achievement"\r\n        if period_grouping in ["Month", "Quarter", "Calendar Year", "Project Year"] and layout_mode == "Period Matrix":\r\n            matrix_row[target_key] = float(matrix_row.get(target_key) or 0) + target_value\r\n            matrix_row[actual_key] = float(matrix_row.get(actual_key) or 0) + actual_value\r\n        else:\r\n            matrix_row[target_key] = target_value\r\n            matrix_row[actual_key] = actual_value\r\n        matrix_target = float(matrix_row.get(target_key) or 0)\r\n        matrix_actual = float(matrix_row.get(actual_key) or 0)\r\n        matrix_row[achievement_key] = matrix_actual * 100 / matrix_target if matrix_target > 0 else 0\r\n\r\n    ordered_periods = []\r\n    for registry_value in period_registry:\r\n        inserted = False\r\n        sort_value = registry_value.split("|||", 1)[0]\r\n        position = 0\r\n        for existing in ordered_periods:\r\n            if sort_value < existing.split("|||", 1)[0]:\r\n                ordered_periods.insert(position, registry_value)\r\n                inserted = True\r\n                break\r\n            position += 1\r\n        if not inserted:\r\n            ordered_periods.append(registry_value)\r\n\r\n    columns = [\r\n        {"label": _("Project"), "fieldname": "project", "fieldtype": "Link", "options": "Project", "width": 125},\r\n        {"label": _("Project Name"), "fieldname": "project_name", "fieldtype": "Data", "width": 200},\r\n        {"label": _("Result"), "fieldname": "result_title", "fieldtype": "Data", "width": 180},\r\n        {"label": _("Indicator Code"), "fieldname": "indicator_code", "fieldtype": "Data", "width": 95},\r\n        {"label": _("Indicator"), "fieldname": "indicator_statement", "fieldtype": "Data", "width": 260},\r\n        {"label": _("Unit"), "fieldname": "unit_of_measure", "fieldtype": "Data", "width": 80},\r\n        {"label": _("Aggregation"), "fieldname": "aggregation_method", "fieldtype": "Data", "width": 135},\r\n        {"label": _("Baseline"), "fieldname": "baseline", "fieldtype": "Float", "width": 80},\r\n        {"label": _("LOA Target"), "fieldname": "overall_target", "fieldtype": "Float", "width": 90}\r\n    ]\r\n    for registry_value in ordered_periods:\r\n        parts = registry_value.split("|||")\r\n        label = parts[1]\r\n        token = parts[2]\r\n        if matrix_measure in ["Target and Actual", "Target Only"]:\r\n            columns.append({"label": label + " " + _("Target"), "fieldname": "p_" + token + "_target", "fieldtype": "Float", "width": 100})\r\n        if matrix_measure in ["Target and Actual", "Actual Only"]:\r\n            columns.append({"label": label + " " + _("Actual"), "fieldname": "p_" + token + "_actual", "fieldtype": "Float", "width": 100})\r\n        if matrix_measure in ["Target and Actual", "Achievement %"]:\r\n            columns.append({"label": label + " %", "fieldname": "p_" + token + "_achievement", "fieldtype": "Percent", "width": 85})\r\n    rows = []\r\n    for matrix_key in matrix_map:\r\n        rows.append(matrix_map[matrix_key])\r\n\r\npriority_rows = []\r\nnormal_rows = []\r\nfor row in rows:\r\n    if row.get("performance_status") in ["Critical", "At Risk"]:\r\n        priority_rows.append(row)\r\n    else:\r\n        normal_rows.append(row)\r\nrows = priority_rows + normal_rows\r\n\r\ntotal_rows = len(rows)\r\nachieved = 0\r\non_track = 0\r\nneeds_attention = 0\r\ncritical = 0\r\nnot_updated = 0\r\ntotal_achievement = 0.0\r\nachievement_count = 0\r\nfor row in rows:\r\n    status = row.get("performance_status")\r\n    if status in ["Target Achieved", "Exceeded Target"]:\r\n        achieved += 1\r\n    elif status == "On Track":\r\n        on_track += 1\r\n    elif status == "At Risk":\r\n        needs_attention += 1\r\n    elif status == "Critical":\r\n        critical += 1\r\n    if row.get("last_result_date") is None and layout_mode == "Period Rows":\r\n        not_updated += 1\r\n    if float(row.get("cumulative_target") or 0) > 0:\r\n        total_achievement += float(row.get("achievement_percentage") or 0)\r\n        achievement_count += 1\r\naverage_achievement = total_achievement / achievement_count if achievement_count else 0\r\nreport_summary = [\r\n    {"value": total_rows, "indicator": "Blue", "label": _("Indicator Records"), "datatype": "Int"},\r\n    {"value": achieved, "indicator": "Green", "label": _("Achieved / Exceeded"), "datatype": "Int"},\r\n    {"value": on_track, "indicator": "Green", "label": _("On Track"), "datatype": "Int"},\r\n    {"value": needs_attention, "indicator": "Orange", "label": _("At Risk"), "datatype": "Int"},\r\n    {"value": critical, "indicator": "Red", "label": _("Critical"), "datatype": "Int"}\r\n]\r\nif not_updated:\r\n    report_summary.append({"value": not_updated, "indicator": "Orange", "label": _("Not Updated"), "datatype": "Int"})\r\nif average_achievement > 0:\r\n    report_summary.append({"value": round(average_achievement, 1), "indicator": "Blue", "label": _("Average Achievement"), "datatype": "Percent"})\r\n\r\nchart_by = filters.get("chart_by") or "Performance Status"\r\nchart_counts = {}\r\nfor row in rows:\r\n    key = row.get("performance_status") or _("Not Assessed")\r\n    if chart_by == "Project": key = row.get("project_name") or row.get("project") or _("Not Specified")\r\n    elif chart_by == "Result": key = row.get("result_title") or _("Not Specified")\r\n    elif chart_by == "Indicator Level": key = row.get("indicator_level") or _("Not Specified")\r\n    elif chart_by == "Data Quality": key = row.get("data_quality") or _("Not Assessed")\r\n    elif chart_by == "Aggregation Method": key = row.get("aggregation_method") or _("Not Specified")\r\n    chart_counts[key] = chart_counts.get(key, 0) + 1\r\nchart_labels = []\r\nchart_values = []\r\nfor key in chart_counts:\r\n    chart_labels.append(key)\r\n    chart_values.append(chart_counts[key])\r\nchart = {"data": {"labels": chart_labels, "datasets": [{"name": _("Indicators"), "values": chart_values}]}, "type": "donut" if chart_by in ["Performance Status", "Data Quality"] else "bar", "height": 320, "colors": ["#2E7D32", "#1565C0", "#F9A825", "#C62828", "#6A1B9A", "#00838F"]}\r\n\r\nmessage = ""\r\nif not rows:\r\n    message = _("No indicator performance records match the selected filters. Confirm that Indicator Target Plans exist for the selected indicators.")\r\nelif layout_mode == "Cumulative Matrix":\r\n    message = _("Cumulative Matrix uses approved Project Progress Updates and the indicator aggregation method. Indicators without approved results show zero actual values.")\r\nelif layout_mode == "Period Matrix":\r\n    message = _("Period Matrix shows period-specific targets and approved actual results.")\r\n\r\ndata = (columns, rows, message, chart, report_summary, 1)\r\n'
def _apply_native_sticky(result):
    if not result:
        return result
    values = list(result) if isinstance(result, (tuple, list)) else [result]
    if not values:
        return result
    columns = values[0] or []
    for index, column in enumerate(columns):
        if isinstance(column, dict):
            column["sticky"] = bool(index < 2)
    values[0] = columns
    return tuple(values)

def execute(filters=None):
    local_vars={"filters":filters or {}}
    safe_exec(REPORT_SCRIPT,None,local_vars,script_filename='Indicator Performance')
    return finalize_report_result(local_vars.get("data") or ([], []))
